def tab(d,w):
    t=Table(d,colWidths=w);t.setStyle(TableStyle([("FONTSIZE",(0,0),(-1,-1),8.5),("BACKGROUND",(0,0),(-1,0),colors.HexColor("#f5b82e")),("GRID",(0,0),(-1,-1),.3,colors.grey)]));return t
zo=[o["b"][i]/o["se"][i] for i in range(4)];zl=[l["b"][i]/l["se"][i] for i in range(4)]

NET=json.load(open("net.json",encoding="utf8"));ST=pd.read_csv("daddy_yankee_streaming_milestones.csv")
_t=[["Collaborator","Songs","Years","Best Latin peak"]]+[[r["collaborator"],r["songs"],f"{r['first']}-{r['last']}",int(r["best_latin"]) if r["best_latin"]!="" else "-"] for r in NET["top"][:10]]
_s=[["Item","Metric","Value","Source"]]+[[Paragraph(str(x),ParagraphStyle("x",fontSize=7.2,leading=8.6)) for x in (r.item,r.metric,r.value,r.source)] for r in ST.itertuples()]

R2=json.load(open("results2.json",encoding="utf8"));AL=pd.read_csv("daddy_yankee_albums.csv").dropna(subset=["us_sales"])
_r=[["Check","Result"],["Spearman rank correlation, year vs Latin peak",f"rho={R2['rho']}, p={R2['p']} (n={R2['n']})"],["Bootstrap 95% interval, OLS year slope (3,000 resamples)",f"{R2['boot_lo']} to {R2['boot_hi']} places per year"],["Kruskal-Wallis, Latin peak across eras",f"H={R2['kw_h']}, p={R2['kw_p']}"],["Spearman after dropping 2022 releases",f"rho={R2['rho_no22']}, p={R2['p_no22']} (n={R2['n_no22']})"]]
